// verifyReviewBundle verifies scope once per operation of the same project and
// resolver, and refuses a scope already being verified: sealed children are
// data, and a cycle among them must end in a named refusal (spec
// pose-review-approval-follows-children R6).
func (s Store) verifyReviewBundle(scope string) (ReviewBundleVerification, error) {
	s = s.reviewOperation()
	state := s.reviewReuse
	key := fmt.Sprintf("%s\x00%t\x00%s", s.Root, s.FederatedResolver != nil, scope)
	if result, ok := state.children[key]; ok {
		return result.verification, result.err
	}
	if state.verifying[key] {
		return ReviewBundleVerification{}, fmt.Errorf("pose: the sealed children of %s form a cycle", scope)
	}
	state.verifying[key] = true
	defer delete(state.verifying, key)
	if s.onReviewVerify != nil {
		s.onReviewVerify(scope)
	}
	verification, err := s.proportionalReviewVerification(scope)
	state.children[key] = childVerificationResult{verification, err}
	return verification, err
}

// proportionalReviewVerification is the verification of a scope, and of a milestone that
// owes no review of its own: one made of a single closed, approved spec, or one a roadmap
// declares. Every reader of an approval comes through here, so they give one answer (ADR
// a-milestone-of-one-member-is-that-member). A negative review recorded on it stands.
func (s Store) proportionalReviewVerification(scope string) (ReviewBundleVerification, error) {
	own, err := s.computeReviewVerification(scope)
	if err != nil || own.Approved {
		return own, err
	}
	ref, parseErr := ParseScopeRef(scope)
	if parseErr != nil || (ref.Kind != "milestone" && ref.Kind != "roadmap") {
		return own, nil
	}
	// A policy without bundles answers through its review attempts alone, and has no
	// bundle of the spec to stand on.
	policy, err := s.GetReviewPolicy()
	if err != nil || !policy.ReviewBundles {
		return own, nil
	}
	if s.milestoneReviewRefused(scope) {
		return own, nil
	}
	// An adopted closeout review policy is the only rule for an open scope:
	// legacy inheritance and declared exemptions cannot weaken `always`, and
	// the policy's own exemption reads the same gate as reviewCheck. A roadmap
	// closed before adoption keeps the legacy reading below.
	adopted := policy.CloseoutReviewAdopted() && !s.closeoutScopeHistorical(ref)
	if adopted {
		decision, exempt, gateErr := s.closeoutReviewGate(scope, policy)
		if gateErr != nil || decision == nil || !exempt || !decision.Known {
			return own, nil
		}
		if ref.Kind == "milestone" && s.FederatedResolver != nil {
			acceptance, err := s.FederatedMilestoneAcceptance(s.FederatedProjectID, ref.Roadmap, ref.Milestone, *s.FederatedResolver)
			if err != nil || !acceptance.Ready {
				return own, nil
			}
		}
		return ReviewBundleVerification{
			Scope: scope, State: "closed", Fresh: true, Approved: true, NextAction: "none",
			Warnings:       []string{closeoutExemptionWarning(scope, *decision)},
			ApprovalOrigin: closeoutApprovalOrigin(*decision), inherited: true,
		}, nil
	}
	if ref.Kind != "milestone" {
		return own, nil
	}
	// Edges still bind: a milestone inherits a review, not the acceptance of what it
	// depends on, and revoked trust or an open predecessor leaves it where it was.
	if s.FederatedResolver != nil {
		acceptance, err := s.FederatedMilestoneAcceptance(s.FederatedProjectID, ref.Roadmap, ref.Milestone, *s.FederatedResolver)
		if err != nil || !acceptance.Ready {
			return own, nil
		}
	}
	if member, ok := s.soleMemberOf(ref); ok {
		child, err := s.verifyReviewBundle("spec:" + member)
		if err == nil && child.State == "closed" && child.Fresh && child.Approved {
			return ReviewBundleVerification{
				Scope: scope, State: "closed", Bundle: child.Bundle, Attestation: child.Attestation, Fresh: true, Approved: true,
				NextAction: "none", Warnings: []string{"the approval of " + scope + " is inherited from spec:" + member + ", its only member"},
				ApprovalOrigin: "inherited:spec:" + member, inherited: true,

