func (s Store) reviewBundleChildren(scope ScopeRef) ([]ReviewBundleChild, []string, error) {
	refs, err := s.reviewBundleChildRefs(scope)
	if err != nil {
		return nil, nil, err
	}
	s = s.reviewOperation()
	parentDone, _ := s.scopeLifecycleDone(scope)
	children, blockers := []ReviewBundleChild{}, []string{}
	for _, ref := range refs {
		if verification, err := s.verifyReviewBundle(ref); err == nil && verification.inherited {
			// A declared milestone has no bundle to seal over: the reason is in the
			// roadmap, which this bundle seals.
			if verification.Bundle != nil {
				children = append(children, ReviewBundleChild{Scope: ref, BundleID: verification.Bundle.BundleID, BundleDigest: verification.Bundle.BundleDigest})
			}
			continue
		}
		sealed, err := s.CurrentReviewBundle(ref)
		if err != nil {
			return nil, nil, err
		}
		if sealed == nil {
			retained, why := s.retainedChildReviewBundle(ref)
			if retained == nil {
				blockers = append(blockers, "child "+ref+" has no sealed review bundle"+why)
				continue
			}
			sealed = retained
		} else if why := s.childReviewStanding(ref, parentDone); why != "" {
			blockers = append(blockers, reviewChildPrefix+ref+" does not stand: "+why)
		}
		children = append(children, ReviewBundleChild{Scope: ref, BundleID: sealed.BundleID, BundleDigest: sealed.BundleDigest})
	}
	return children, blockers, nil
}

// retainedChildReviewBundle is the approved review a done child keeps after
// later commits changed what is prepared for it: the bundle the child's own
// verification retains, with every condition that verification applies —
// lost attestation history, a later negative review, a changed federated
// manifest — or nil and why not (spec pose-review-subject-later-removal R3).
func (s Store) retainedChildReviewBundle(ref string) (*ReviewBundle, string) {
	verification, err := s.reviewOperation().verifyReviewBundle(ref)
	if err != nil {
		return nil, ": its review could not be verified: " + err.Error()
	}
	if verification.State != "closed" || !verification.Fresh || !verification.Approved || verification.Bundle == nil {
		if len(verification.Blockers) > 0 {
			return nil, ": " + strings.Join(uniqueSorted(verification.Blockers), "; ")
		}
		return nil, ""
	}
	return verification.Bundle, ""
}

// reviewChildPrefix opens every blocker that names a child of the scope.
